<?php declare(strict_types=1);
$accessories=$inventory->accessories($itemId);$accessoryDraft=input($_POST,'action')==='inventory-accessories'&&is_array($_POST['data']['accessories']??null)?$_POST['data']['accessories']:array_map(static fn($r)=>['child'=>$r['child_id'],'quantity_per_unit'=>$r['quantity_per_unit'],'usage_mode'=>$r['usage_mode']??'required'],$accessories);
$accessoryOptions=[''=>'Bitte Zubehör auswählen'];foreach($inventory->items(['status'=>'active']) as $candidate)if($candidate['id']!==$itemId)$accessoryOptions[$candidate['id']]=$candidate['name'].' · '.$candidate['unit'];foreach($accessories as $old)if(!isset($accessoryOptions[$old['child_id']]))$accessoryOptions[$old['child_id']]=$old['name'].' (archiviert – Zuordnung entfernen)';
?>
<section class="card"><h2>Zubehör / Packliste</h2><p>Was gehört zu einer Einheit dieses Gegenstands? Die Packliste bucht, reserviert und verdoppelt keinen Bestand. Zubehör wird als eigener Gegenstand geführt.</p>
<?php foreach($accessories as $accessory):$needed=$pieceTotal*(int)$accessory['quantity_per_unit']; ?><p class="iv-piece-summary"><?= e($accessory['name']) ?>: <?= (int)$accessory['quantity_per_unit'] ?> <?= e($accessory['unit']) ?> je <?= e($item['unit']) ?>; <?= ($accessory['usage_mode']??'required')==='optional'?'bei Auswahl für':'für' ?> <?= $pieceTotal ?> <?= e($item['unit']) ?> brauchen Sie <?= $needed ?> <?= e($accessory['unit']) ?><?php if((int)$accessory['content_quantity']>1): ?> (<?= $needed*(int)$accessory['content_quantity'] ?> <?= e($accessory['content_unit']) ?> Inhalt)<?php endif ?>. <?= ($accessory['usage_mode']??'required')==='optional'?'Bei Bedarf / alternative Höhe.':'Immer dabei.' ?> <?= !$accessory['active']?'Zubehör archiviert.':'' ?></p><?php endforeach ?>
<?php if($ivWrite&&$item['active']): ?><form method="post" data-accessory-form><?= ivPost('accessories',$itemId,(int)$item['version']) ?><div data-accessory-rows><?php foreach(array_values($accessoryDraft?:[['child'=>'','quantity_per_unit'=>'1']]) as $index=>$accessory): ?><div data-accessory-row class="iv-form-grid"><label>Zubehörgegenstand<select class="form-control" name="data[accessories][<?= $index ?>][child]" data-select-search><?php foreach($accessoryOptions as $id=>$label): ?><option value="<?= e($id) ?>" <?= ($accessory['child']??'')===$id?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label><label>Menge je <?= e($item['unit']) ?><input class="form-control" type="number" min="1" max="1000000" name="data[accessories][<?= $index ?>][quantity_per_unit]" value="<?= e($accessory['quantity_per_unit']??1) ?>"></label><label>Wann mitnehmen?<select class="form-control" name="data[accessories][<?= $index ?>][usage_mode]"><option value="required" <?= ($accessory['usage_mode']??'required')==='required'?'selected':'' ?>>Immer dabei</option><option value="optional" <?= ($accessory['usage_mode']??'required')==='optional'?'selected':'' ?>>Bei Bedarf / alternative Höhe</option></select></label><button type="button" class="btn btn-outline theme-secondary secondary" data-accessory-remove>Zuordnung entfernen</button></div><?php endforeach ?></div><button type="button" class="btn btn-outline theme-secondary secondary" data-accessory-add>Weiteres Zubehör</button><button class="btn btn-solid theme-primary">Zubehörzuordnung speichern</button></form><script defer src="inventory-accessories.js?v=1"></script><?php endif ?></section>
